import{_ as t,a,c as i,ac as l}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 73 The record-holder","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 73 The record-holder","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 72 A car called Bluebird","link":"/life/english/new-concept/book-2/unit-03/lesson-072"},"next":{"text":"第二册：实践与进步 · Lesson 74 Out of the limelight","link":"/life/english/new-concept/book-2/unit-04/lesson-074"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 72 A car called Bluebird","link":"/life/english/new-concept/book-2/unit-03/lesson-072"},"next":{"text":"第二册：实践与进步 · Lesson 74 Out of the limelight","link":"/life/english/new-concept/book-2/unit-04/lesson-074"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-073.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-073.md"}'),o={name:"life/english/new-concept/book-2/unit-04/lesson-073.md"};function r(n,e,s,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="第二册-实践与进步-·-lesson-73-the-record-holder" tabindex="-1">第二册：实践与进步 · Lesson 73 The record-holder <a class="header-anchor" href="#第二册-实践与进步-·-lesson-73-the-record-holder" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 73 The record-holder&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>孩子反复旅行并不一定意味着拥有独立旅行能力，记录需要准确说明范围；练习持续时间与经历次数。本课的语言观察是：has travelled alone three times 是截至现在的经历次数；has been travelling 强调过程。alone 指没有同行者，不等于没有任何服务人员提供帮助。完成学习后，请写一个学习或旅行纪录，交代统计时间、次数和能力边界。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>border</td><td>/ˈbɔːdə/</td><td>n.</td><td>边界</td><td>cross a border</td></tr><tr><td>travel</td><td>/ˈtrævəl/</td><td>v.</td><td>旅行</td><td>travel widely</td></tr><tr><td>limit</td><td>/ˈlɪmɪt/</td><td>n.</td><td>限制</td><td>a time limit</td></tr><tr><td>child</td><td>/tʃaɪld/</td><td>n.</td><td>孩子</td><td>a young child</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>hold a record — 保持一项纪录</li><li>so many times — 如此多次，times 表次数可数</li></ul><h2 id="语法讲解-现在完成时与过去时间" tabindex="-1">语法讲解：现在完成时与过去时间 <a class="header-anchor" href="#语法讲解-现在完成时与过去时间" aria-label="Permalink to &quot;语法讲解：现在完成时与过去时间&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：has travelled alone three times 是截至现在的经历次数；has been travelling 强调过程。alone 指没有同行者，不等于没有任何服务人员提供帮助。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Ella has crossed the border with her family five times this year.</p></blockquote><p>埃拉今年已经和家人一起过境五次了。</p><p>has crossed 是完成时，five times 为次数，with her family 明确同行者，this year 的范围包含现在。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>five time 应为 five times；不要把 times 误译成五点钟。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>比较 five times 与 five o&#39;clock 的节奏；重读 with her family 避免误解为独行。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Ella has crossed the border with her family five times this year. She can now explain the route to her younger brother. An adult still checks all the documents.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一个学习或旅行纪录，交代统计时间、次数和能力边界。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：has crossed 是完成时，five times 为次数，with her family 明确同行者，this year 的范围包含现在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：five time 应为 five times；不要把 times 误译成五点钟。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 cross：Ella has ___ the border five times.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> crossed</p><p><strong>解析：</strong> 完成时要求过去分词 crossed。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>谁仍负责核对全部文件？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> An adult.</p><p><strong>解析：</strong> 能解释路线不等于孩子独立承担文件检查。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“到目前为止三次”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> three times so far</p><p><strong>解析：</strong> times 表次数，so far 将统计范围延伸到现在。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在完成时与过去时间。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-072">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-074">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
